import{read,write}from './storage.js';import{esc,toast}from './ui.js';
import{prayerCourses as prayers,savedLesson,validPosition}from './learning-state.js';
import{learningIllustration}from './learning-illustrations.js';
import{recordingFor,allowedLessonAudio}from './sourced-audio.js';
let data=null,quran=null,host=null,session=null,audio=null,audioIndex=0,repeat=false,generation=0,audioEpoch=0;
export function stopLearning(){generation++;stopAudio();document.body.classList.remove('learning-focus')}
function stopAudio(){audioEpoch++;if(audio){audio.onended=null;audio.onerror=null;audio.pause();audio.src='';audio=null}repeat=false}
function sourceLink(id){const s=data.sources[id];return s?'<a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.label)+'</a>':''}
export function buildPrayerSequence(data,key){const prayer=prayers[key];if(!prayer)throw Error('Неизвестная молитва');const find=id=>({...data.steps.find(s=>s.id===id)});let sequence=['prepare','intention','takbir'].map(find);for(let r=1;r<=prayer.rakats;r++){if(r>1)sequence.push({...find('next'),title:'Встать на '+r+'-й ракаат',text:'Со словами такбира встаньте для следующего ракаата.',rakat:r});for(const id of['qiyam','fatiha',...(r<=2?['surah']:[]),'ruku','rise','sujud','between','sujud2'])sequence.push({...find(id),rakat:r});if(r===2&&r<prayer.rakats)sequence.push({...find('tashahhud'),title:'Первое сидение · ташаххуд',rakat:r,text:'После второго ракаата сядьте и прочитайте ташаххуд. Затем продолжайте молитву; заключительные действия будут после последнего ракаата.'});if(r===prayer.rakats)for(const id of['tashahhud','salawat','dua','taslim'])sequence.push({...find(id),rakat:r})}return sequence}
export async function showLearning(container,entry=null){host=container;const token=++generation;host.innerHTML='<div class="section panel"><h2>Изучить намаз</h2><p class="muted">Открываем материалы…</p></div>';try{if(!data){const values=await Promise.all(['learning-content.json','learning-quran.json'].map(async file=>{const response=await fetch('./data/'+file);if(!response.ok)throw Error();return response.json()}));if(token!==generation)return;[data,quran]=values}if(token!==generation)return;if(entry==='resume'){const saved=savedLesson(read('learning-progress',null));if(saved)start(saved.kind,saved.index,saved.returnTo);else hub()}else if(entry==='basic'||entry==='wudu')start(entry,0);else if(entry==='guide'){stopAudio();session=null;prayerChooser()}else if(session?.complete)complete();else if(session)lesson();else hub()}catch{if(token!==generation)return;host.innerHTML='<section class="panel section"><h2>Материалы недоступны</h2><p class="muted">Проверьте соединение или откройте ранее сохранённые материалы.</p><button class="button" id="learn-retry">Повторить</button></section>';host.querySelector('#learn-retry').onclick=()=>showLearning(host,entry)}}
function hub(){document.body.classList.remove('learning-focus');const saved=savedLesson(read('learning-progress',null));host.innerHTML='<div class="page-head"><div><h1>Изучить намаз</h1><p class="muted">Спокойно. По одному шагу.</p></div></div><div class="learning-hub"><section class="panel learning-intro"><span class="eyebrow">НАЧНИТЕ С ОСНОВ</span><h2>Каждый шаг понятен</h2><p class="muted">Единое обучение: движение, текст и источник на одном экране. Значимые различия поясняются в соответствующих шагах.</p><div class="button-row"><button class="button" data-start="basic">Порядок намаза · 17 шагов</button><button class="button secondary" data-start="wudu">Омовение · 10 шагов</button></div>'+(saved&&!saved.complete?'<button class="text-button" id="resume">Продолжить с шага '+(saved.index+1)+'</button>':'')+'</section><section class="panel learning-prayers"><span class="eyebrow">ПРОВЕДИ МЕНЯ ЧЕРЕЗ НАМАЗ</span><h2>Выберите молитву</h2><p class="muted">Учебный порядок фарда для самостоятельной молитвы. Это обучение, а не таймер совершения намаза.</p><div class="prayer-choice-grid">'+Object.entries(prayers).map(([k,p])=>'<button data-start="'+k+'"><strong>'+p.name+'</strong><span>'+p.rakats+' ракаата фарда</span></button>').join('')+'</div><p class="muted">Витр, сунна, молитва за имамом и особенности поездки изучаются отдельно. Пояснения к различиям доступны в самих уроках.</p></section><section class="panel"><h2>Тексты и произношение</h2><p class="muted">Коранические тексты взяты из Al Quran Cloud. Перевод: Эльмир Кулиев. Аудио сур: Мишари аль-Афаси.</p><p class="muted">Транслитерация — вспомогательная запись, она не передаёт все звуки арабского. Для остальных формул проверенная аудиозапись пока не подключена.</p><a class="text-button" href="#sources">Источники SALAH</a></section></div>';host.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start,0));host.querySelector('#resume')?.addEventListener('click',()=>start(saved.kind,saved.index,saved.returnTo))}
function prayerChooser(){document.body.classList.remove('learning-focus');host.innerHTML='<a class="text-button" href="#knowledge">← Знания</a><div class="page-head"><div><h1>Намаз шаг за шагом</h1></div></div><section class="panel learning-prayers"><h2>Выберите молитву</h2><p class="muted">Учебный порядок фарда для самостоятельной молитвы. Это обучение, а не таймер совершения намаза.</p><div class="prayer-choice-grid">'+Object.entries(prayers).map(([k,p])=>'<button data-start="'+k+'"><strong>'+p.name+'</strong><span>'+p.rakats+' ракаата фарда</span></button>').join('')+'</div><p class="muted">Значимые различия в деталях разобраны рядом с соответствующими шагами.</p></section>';host.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start,0));}
function start(kind,index,returnTo=null){
 if(!validPosition({kind,index})){hub();return}
 const sequence=kind==='basic'?data.steps:kind==='wudu'?data.wudu:buildPrayerSequence(data,kind);
 if(index>=sequence.length){hub();return}
 session={kind,index,sequence,returnTo:kind==='wudu'&&validPosition(returnTo)&&returnTo.kind!=='wudu'?{kind:returnTo.kind,index:returnTo.index}:null};
 persist();lesson();window.scrollTo(0,0)
}
function persist(complete=false){const progress={kind:session.kind,index:session.index,complete};if(session.returnTo)progress.returnTo=session.returnTo;if(!write('learning-progress',progress))toast('Прогресс не удалось сохранить')}
function fiqhInfo(type){
const notes={
hands:{text:'Высота поднятия и положение сложенных рук могут отличаться. Иллюстрация показывает только один пример.',refs:['hanafi','shafii','hanbali']},
wuduHead:{text:'В этом уроке предложено протереть голову; обязательный объём и детали зависят от школы.',refs:['wuduGuide']},
finger:{text:'Положение и движение указательного пальца различаются. Здесь приводится текст Ибн Мас‘уда, а не единственный вариант ташаххуда.',refs:['tashahhud','maliki']},
sitting:{text:'Формы сидения, особенно в заключительном ракаате, различаются. Схема показывает общий силуэт без уточнения различающихся деталей.',refs:['positions','hanafi']},
recitation:{text:'Этот сценарий предназначен для самостоятельной молитвы. Чтение за имамом, басмала и «Амин» имеют отдельные правила.',refs:['fatiha','hanafi']},
taslim:{text:'Здесь показан вариант приветствия направо и налево. В маликитской школе есть особенности завершения, которые требуют отдельного разбора.',refs:['taslim']},
posture:{text:'Детали положений тела для мужчин и женщин рассматриваются по-разному в руководствах школ.',refs:['positions','hanafi']},
intention:{text:'Намерение относится к сердцу; в некоторых руководствах допускается или рекомендуется его словесное выражение.',refs:['intention','hanafi']}
};
const note=notes[type]||notes.intention;
return '<details class="fiqh-detail"><summary>Есть различия в фикхе</summary><p>'+esc('В этом вопросе существуют различия между правовыми школами. '+note.text)+'</p><div class="lesson-sources">'+note.refs.map(sourceLink).join(' · ')+'</div></details>'
}
function getPassage(step){if(step.formula){const f=data.formulas[step.formula],recording=recordingFor('learning',step.formula,f.arabic);return{...f,transliteration:f.translit,audios:recording?[recording.url]:[],recording}}if(typeof step.quran==='number'){const q=quran[step.quran];return{verses:q.verses,audios:q.verses.map(v=>v.audio),source:'quran',author:q.translationAuthor}}if(step.quran==='dua'){const arabic=quran.dua.find(d=>d.edition==='quran-uthmani').text;const tr=quran.dua.find(d=>d.edition==='ru.kuliev').text;const translit=quran.dua.find(d=>d.edition==='en.transliteration').text;return{arabic:arabic.slice(arabic.indexOf('رَبَّنَا')),translation:tr.slice(tr.indexOf('«')+1).replace(/».?$/,''),transliteration:translit.slice(translit.indexOf('rabbana')),audios:[],source:'quran',author:'Эльмир Кулиев · фрагмент Корана 2:201'}}return null}
function passageHtml(p,title){if(!p)return'';const verses=p.verses||[{arabic:p.arabic,translation:p.translation,transliteration:p.transliteration}];return '<details class="lesson-passage" open><summary class="passage-toggle">'+esc(title)+'<span>Свернуть / развернуть</span></summary><div class="passage-body">'+verses.map(v=>'<div class="lesson-verse"><p class="arabic" dir="rtl" lang="ar">'+esc(v.arabic)+'</p><details class="transliteration" open><summary>Транслитерация'+(p.verses?' · латиницей':'')+'</summary><p>'+esc(v.transliteration)+'</p></details><p class="lesson-translation">'+esc(v.translation)+'</p></div>').join('')+'<p class="lesson-author">'+esc(p.author||'Пояснение смысла на русском · сверено с указанным хадисом')+'</p><div class="lesson-audio"><button class="button secondary" id="lesson-play" '+(!p.audios.length?'disabled':'')+'>▶ Прослушать</button>'+(p.audios.length?'<label><input type="checkbox" id="lesson-repeat"> Повторять</label>':'<span>Проверенная аудиозапись пока недоступна</span>')+'</div>'+(p.recording?'<p class="lesson-author">Запись HisnMuslim</p>':'')+'</div></details>'}
function lesson(){stopAudio();document.body.classList.add('learning-focus');const step=session.sequence[session.index],p=getPassage(step);const storedSize=Number(read('learning-font-size',20));const fontSize=[18,20,24,28].includes(storedSize)?storedSize:20;const name=session.kind==='basic'?'Порядок намаза':session.kind==='wudu'?'Омовение':prayers[session.kind].name;host.innerHTML='<div class="lesson-shell" style="--reading-size:'+fontSize+'px;--arabic-size:'+(fontSize*1.8)+'px"><div class="lesson-top"><button id="lesson-exit" class="text-button">Закрыть</button><span>'+esc(name)+'</span><span>Шаг '+(session.index+1)+' из '+session.sequence.length+'</span></div><div class="progress"><span style="width:'+((session.index+1)/session.sequence.length*100)+'%"></span></div><div class="reading-settings"><label for="reading-size">Размер текста</label><select id="reading-size">'+[18,20,24,28].map(n=>'<option value="'+n+'" '+(fontSize===n?'selected':'')+'>'+n+' px</option>').join('')+'</select></div><section class="lesson-content">'+(step.rakat?'<span class="eyebrow">РАКААТ '+step.rakat+' ИЗ '+prayers[session.kind].rakats+'</span>':'<span class="eyebrow">'+(session.kind==='wudu'?'ОМОВЕНИЕ':'ОСНОВЫ НАМАЗА')+'</span>')+'<h1>'+esc(step.title)+'</h1>'+(step.pose?'<div class="lesson-pose '+step.pose+'" role="img" aria-label="'+esc(step.title)+': схематичный пример положения тела"></div><p class="pose-caption">Схематичный пример. Детали положения описаны ниже.</p>':learningIllustration(step))+'<p class="lesson-instruction">'+esc(step.text)+'</p>'+(step.times?'<span class="repetition-chip">'+esc(step.times)+'</span>':'')+(step.action==='wudu'?'<button id="open-wudu" class="button secondary">Пройти омовение</button>':step.action==='qibla'?'<a href="#qibla" class="text-button">Открыть Киблу</a>':'')+passageHtml(p,step.title)+(step.fiqh?fiqhInfo(step.fiqh):'')+'<div class="lesson-sources">Источник: '+sourceLink(step.source)+(p?.source&&p.source!==step.source?' · '+sourceLink(p.source):'')+'</div></section><div class="lesson-controls"><span>← Свайп влево — '+(session.index===session.sequence.length-1?'завершить':'дальше')+'<br>Свайп вправо — назад →</span></div></div>';host.querySelector('#lesson-exit').onclick=()=>{stopAudio();session=null;location.hash='knowledge'};bindLessonNavigation();host.querySelector('#reading-size').onchange=e=>{const n=Number(e.target.value);write('learning-font-size',n);const shell=host.querySelector('.lesson-shell');shell.style.setProperty('--reading-size',n+'px');shell.style.setProperty('--arabic-size',n*1.8+'px')};;host.querySelector('#open-wudu')?.addEventListener('click',()=>start('wudu',0,{kind:session.kind,index:session.index}));if(p?.audios.length){host.querySelector('#lesson-play').onclick=()=>{if(audio&&!audio.paused){audio.pause();host.querySelector('#lesson-play').textContent='▶ Продолжить';return}repeat=host.querySelector('#lesson-repeat').checked;if(audio){host.querySelector('#lesson-play').textContent='Ⅱ Пауза';const current=audio,epoch=audioEpoch;current.play().catch(()=>{if(current===audio&&epoch===audioEpoch)audioError()})}else{audioIndex=0;playPart(p.audios)}};host.querySelector('#lesson-repeat').onchange=e=>repeat=e.target.checked}}
function audioError(){stopAudio();toast('Аудио временно недоступно. Проверьте соединение.');const b=host.querySelector('#lesson-play');if(b)b.textContent='▶ Прослушать'}
function playPart(urls){const url=urls[audioIndex];if(!url||!allowedLessonAudio(url)){audioError();return}const current=audio=new Audio(url),epoch=audioEpoch;const failure=()=>{if(current===audio&&epoch===audioEpoch)audioError()};current.onerror=failure;current.onended=()=>{if(current!==audio||epoch!==audioEpoch)return;audioIndex++;if(audioIndex<urls.length)playPart(urls);else if(repeat){audioIndex=0;playPart(urls)}else{stopAudio();const b=host.querySelector('#lesson-play');if(b)b.textContent='▶ Прослушать'}};const b=host.querySelector('#lesson-play');if(b)b.textContent='Ⅱ Пауза';current.play().catch(failure)}

function complete(){
 session.complete=true;stopAudio();document.body.classList.remove('learning-focus');
 const kind=session.kind,parent=session.returnTo;
 if(parent&&!write('learning-progress',{...parent,complete:false}))toast('Прогресс не удалось сохранить');
 host.innerHTML='<section class="panel section lesson-complete"><span class="eyebrow">ОБУЧЕНИЕ ЗАВЕРШЕНО</span><h1>'+(kind==='wudu'?'Вы прошли порядок омовения':'Вы прошли порядок намаза')+'</h1><p class="muted">'+(parent?'Теперь можно вернуться к уроку намаза.':kind==='wudu'?'Теперь можно перейти к изучению намаза.':'Вы можете повторить материал или открыть отдельную молитву.')+'</p><div class="button-row">'+(parent?'<button class="button" id="lesson-return">Вернуться к намазу</button>':'')+'<button class="button '+(parent?'secondary':'')+'" id="lesson-again">Повторить</button><button class="button secondary" id="lesson-hub">'+(kind==='wudu'?'Изучить намаз':'Выбрать намаз')+'</button>'+(kind!=='wudu'?'<button class="text-button" id="lesson-wudu">Перейти к омовению</button>':'')+'<a class="text-button" href="#knowledge">К знаниям</a></div></section>';
 host.querySelector('#lesson-again').onclick=()=>start(kind,0,parent);
 host.querySelector('#lesson-hub').onclick=()=>{if(kind==='wudu')start('basic',0);else{session=null;prayerChooser();window.scrollTo(0,0)}};
 host.querySelector('#lesson-return')?.addEventListener('click',()=>start(parent.kind,parent.index));
 host.querySelector('#lesson-wudu')?.addEventListener('click',()=>start('wudu',0));
 window.scrollTo(0,0)
}

function moveLesson(direction){if(direction<0&&session.index===0)return;if(direction>0&&session.index===session.sequence.length-1){persist(true);complete();return}session.index+=direction;persist();lesson();window.scrollTo(0,0)}
function bindLessonNavigation(){const shell=host.querySelector('.lesson-shell');shell.tabIndex=0;let gesture=null;shell.addEventListener('pointerdown',e=>{if(e.isPrimary&&e.button===0&&!e.target.closest('button,a,input,select,summary'))gesture={x:e.clientX,y:e.clientY,id:e.pointerId,time:Date.now()}});shell.addEventListener('pointercancel',()=>gesture=null);shell.addEventListener('pointerup',e=>{const g=gesture;gesture=null;if(!g||g.id!==e.pointerId||Date.now()-g.time>1200)return;const dx=e.clientX-g.x,dy=e.clientY-g.y;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.6&&!window.getSelection()?.toString())moveLesson(dx<0?1:-1)});shell.addEventListener('keydown',e=>{if(e.target.closest('input,select,button,a,summary'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();moveLesson(e.key==='ArrowLeft'?1:-1);host.querySelector('.lesson-shell')?.focus({preventScroll:true})}})}
